import{_ as l,a0 as p,w as r,s as o,I as i,x as a,a1 as n,A as e,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"使用 Stratis 的网络绑定磁盘加密 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Stratis 的网络绑定磁盘加密 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Stratis 的网络绑定磁盘加密 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Stratis 的网络绑定磁盘加密 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210407 Using network bound disk encryption with Stratis","title":"使用 Stratis 的网络绑定磁盘加密","tag":"202104","desc":""},"relativePath":"202104/20210407 Using network bound disk encryption with Stratis.md","filePath":"[post].md"}'),g={name:"202104/20210407 Using network bound disk encryption with Stratis.md"};function h(k,s,b,u,c,f){const t=p("Link");return r(),o("div",null,[s[40]||(s[40]=i("h1",{id:"使用-stratis-的网络绑定磁盘加密",tabindex:"-1"},[a("使用 Stratis 的网络绑定磁盘加密 "),i("a",{class:"header-anchor",href:"#使用-stratis-的网络绑定磁盘加密","aria-label":"Permalink to “使用 Stratis 的网络绑定磁盘加密”"},"​")],-1)),s[41]||(s[41]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202104/27/221704gyzyvyroyyrybany.jpg",alt:""})],-1)),i("p",null,[s[1]||(s[1]=a("在一个有许多加密磁盘的环境中，解锁所有的磁盘是一项困难的任务。",-1)),s[2]||(s[2]=i("ruby",null,[a("网络绑定磁盘加密"),i("rt",null,"Network bound disk encryption")],-1)),s[3]||(s[3]=a("（NBDE）有助于自动解锁 Stratis 卷的过程。这是在大型环境中的一个关键要求。Stratis 2.1 版本增加了对加密的支持，这在《",-1)),n(t,{href:"https://linux.cn/article-13311-1.html"},{default:e(()=>[...s[0]||(s[0]=[a("Stratis 加密入门",-1)])]),_:1}),s[4]||(s[4]=a("》一文中介绍过。Stratis 2.3 版本最近在使用加密的 Stratis 池时引入了对网络绑定磁盘加密（NBDE）的支持，这是本文的主题。",-1))]),i("p",null,[n(t,{href:"https://stratis-storage.github.io/"},{default:e(()=>[...s[5]||(s[5]=[a("Stratis 网站",-1)])]),_:1}),s[7]||(s[7]=a(" 将 Stratis 描述为一个“",-1)),s[8]||(s[8]=i("em",null,"易于使用的 Linux 本地存储管理",-1)),s[9]||(s[9]=a("”。短视频《",-1)),n(t,{href:"https://www.youtube.com/watch?v=CJu3kmY-f5o"},{default:e(()=>[...s[6]||(s[6]=[a("使用 Stratis 管理存储",-1)])]),_:1}),s[10]||(s[10]=a("》对基础知识进行了快速演示。该视频是在 Red Hat Enterprise Linux 8 系统上录制的，然而，视频中显示的概念也适用于 Fedora Linux 中的 Stratis。",-1))]),s[42]||(s[42]=i("h3",{id:"先决条件",tabindex:"-1"},[a("先决条件 "),i("a",{class:"header-anchor",href:"#先决条件","aria-label":"Permalink to “先决条件”"},"​")],-1)),i("p",null,[s[13]||(s[13]=a("本文假设你熟悉 Stratis，也熟悉 Stratis 池加密。如果你不熟悉这些主题，请参考这篇 ",-1)),n(t,{href:"https://linux.cn/article-13311-1.html"},{default:e(()=>[...s[11]||(s[11]=[a("文章",-1)])]),_:1}),s[14]||(s[14]=a(" 和前面提到的 ",-1)),n(t,{href:"https://www.youtube.com/watch?v=CJu3kmY-f5o"},{default:e(()=>[...s[12]||(s[12]=[a("Stratis 概述视频",-1)])]),_:1}),s[15]||(s[15]=a("。",-1))]),s[43]||(s[43]=i("p",null,"NBDE 需要 Stratis 2.3 或更高版本。本文中的例子使用的是 Fedora Linux 34 的预发布版本。Fedora Linux 34 的最终版本将包含 Stratis 2.3。",-1)),s[44]||(s[44]=i("h3",{id:"网络绑定磁盘加密-nbde-概述",tabindex:"-1"},[a("网络绑定磁盘加密（NBDE）概述 "),i("a",{class:"header-anchor",href:"#网络绑定磁盘加密-nbde-概述","aria-label":"Permalink to “网络绑定磁盘加密（NBDE）概述”"},"​")],-1)),s[45]||(s[45]=i("p",null,"加密存储的主要挑战之一是有一个安全的方法在系统重启后再次解锁存储。在大型环境中，手动输入加密口令并不能很好地扩展。NBDE 解决了这一问题，允许以自动方式解锁加密存储。",-1)),s[46]||(s[46]=i("p",null,"在更高层次上，NBDE 需要环境中的 Tang 服务器。客户端系统（使用 Clevis Pin）只要能与 Tang 服务器建立网络连接，就可以自动解密存储。如果网络没有连接到 Tang 服务器，则必须手动解密存储。",-1)),s[47]||(s[47]=i("p",null,"这背后的想法是，Tang 服务器只能在内部网络上使用，因此，如果加密设备丢失或被盗，它将不再能够访问内部网络连接到 Tang 服务器，因此不会被自动解密。",-1)),i("p",null,[s[18]||(s[18]=a("关于 Tang 和 Clevis 的更多信息，请参见手册页（",-1)),s[19]||(s[19]=i("code",null,"man tang",-1)),s[20]||(s[20]=a("、",-1)),s[21]||(s[21]=i("code",null,"man clevis",-1)),s[22]||(s[22]=a("）、",-1)),n(t,{href:"https://github.com/latchset/tang"},{default:e(()=>[...s[16]||(s[16]=[a("Tang 的 GitHub 页面",-1)])]),_:1}),s[23]||(s[23]=a(" 和 ",-1)),n(t,{href:"https://github.com/latchset/clevis"},{default:e(()=>[...s[17]||(s[17]=[a("Clevis 的 GitHub 页面",-1)])]),_:1}),s[24]||(s[24]=a("。",-1))]),s[48]||(s[48]=d(`<h3 id="设置-tang-服务器" tabindex="-1">设置 Tang 服务器 <a class="header-anchor" href="#设置-tang-服务器" aria-label="Permalink to “设置 Tang 服务器”">​</a></h3><p>本例使用另一个 Fedora Linux 系统作为 Tang 服务器，主机名为 <code>tang-server</code>。首先安装 <code>tang</code> 包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dnf install tang</span></span></code></pre></div><p>然后用 <code>systemctl</code> 启用并启动 <code>tangd.socket</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl enable tangd.socket --now</span></span></code></pre></div><p>Tang 使用的是 TCP 80 端口，所以你也需要在防火墙中打开该端口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --add-port=80/tcp --permanent</span></span>
<span class="line"><span>firewall-cmd --add-port=80/tcp</span></span></code></pre></div><p>最后，运行 <code>tang-show-keys</code> 来显示输出签名密钥指纹。你以后会需要这个。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tang-show-keys</span></span>
<span class="line"><span>l3fZGUCmnvKQF_OA6VZF9jf8z2s</span></span></code></pre></div><h3 id="创建加密的-stratis-池" tabindex="-1">创建加密的 Stratis 池 <a class="header-anchor" href="#创建加密的-stratis-池" aria-label="Permalink to “创建加密的 Stratis 池”">​</a></h3><p>上一篇关于 Stratis 加密的文章详细介绍了如何设置加密的 Stratis 池，所以本文不会深入介绍。</p><p>第一步是捕获一个将用于解密 Stratis 池的密钥。即使使用 NBDE，也需要设置这个，因为在 NBDE 服务器无法到达的情况下，可以用它来手动解锁池。使用以下命令捕获 <code>pool1</code> 密钥。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis key set --capture-key pool1key</span></span>
<span class="line"><span>Enter key data followed by the return key:</span></span></code></pre></div><p>然后我将使用 <code>/dev/vdb</code> 设备创建一个加密的 Stratis 池（使用刚才创建的 <code>pool1key</code>），命名为 <code>pool1</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool create --key-desc pool1key pool1 /dev/vdb。</span></span></code></pre></div><p>接下来，在这个 Stratis 池中创建一个名为 <code>filesystem1</code> 的文件系统，创建一个挂载点，挂载文件系统，并在其中创建一个测试文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis filesystem create pool1 filesystem1</span></span>
<span class="line"><span># mkdir /filesystem1</span></span>
<span class="line"><span># mount /dev/stratis/pool1/filesystem1 /filesystem1</span></span>
<span class="line"><span># cd /filesystem1</span></span>
<span class="line"><span># echo &quot;this is a test file&quot; &gt; testfile</span></span></code></pre></div><h3 id="将-stratis-池绑定到-tang-服务器上" tabindex="-1">将 Stratis 池绑定到 Tang 服务器上 <a class="header-anchor" href="#将-stratis-池绑定到-tang-服务器上" aria-label="Permalink to “将 Stratis 池绑定到 Tang 服务器上”">​</a></h3><p>此时，我们已经创建了加密的 Stratis 池，并在池中创建了一个文件系统。下一步是将你的 Stratis 池绑定到刚刚设置的 Tang 服务器上。使用 <code>stratis pool bind nbde</code> 命令进行。</p><p>当你进行 Tang 绑定时，需要向该命令传递几个参数：</p><ul><li>池名（在本例中，<code>pool1</code>）</li><li>钥匙描述符名称（本例中为 <code>pool1key</code>）</li><li>Tang 服务器名称（在本例中，<code>http://tang-server</code>）</li></ul><p>记得之前在 Tang 服务器上，运行了 <code>tang-show-keys</code>，显示 Tang 输出的签名密钥指纹是 <code>l3fZGUCmnvKQF_OA6VZF9jf8z2s</code>。除了前面的参数外，还需要用参数 <code>-thumbprint l3fZGUCmnvKQF_OA6VZF9jf8z2s</code> 传递这个指纹，或者用 <code>-trust-url</code> 参数跳过对指纹的验证。</p><p>使用 <code>-thumbprint</code> 参数更安全。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool bind nbde pool1 pool1key http://tang-server --thumbprint l3fZGUCmnvKQF_OA6VZF9jf8z2s</span></span></code></pre></div><h3 id="用-nbde-解锁-stratis-池" tabindex="-1">用 NBDE 解锁 Stratis 池 <a class="header-anchor" href="#用-nbde-解锁-stratis-池" aria-label="Permalink to “用 NBDE 解锁 Stratis 池”">​</a></h3><p>接下来重启主机，并验证你可以用 NBDE 解锁 Stratis 池，而不需要使用密钥口令。重启主机后，该池不再可用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool list</span></span>
<span class="line"><span>Name Total Physical Properties</span></span></code></pre></div><p>要使用 NBDE 解锁池，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool unlock clevis</span></span></code></pre></div><p>注意，你不需要使用密钥口令。这个命令可以在系统启动时自动运行。</p><p>此时，Stratis 池已经可以使用了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool list</span></span>
<span class="line"><span>Name Total Physical Properties</span></span>
<span class="line"><span>pool1 4.98 GiB / 583.65 MiB / 4.41 GiB ~Ca, Cr</span></span></code></pre></div><p>你可以挂载文件系统，访问之前创建的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount /dev/stratis/pool1/filesystem1 /filesystem1/</span></span>
<span class="line"><span># cat /filesystem1/testfile</span></span>
<span class="line"><span>this is a test file</span></span></code></pre></div><h3 id="轮换-tang-服务器密钥" tabindex="-1">轮换 Tang 服务器密钥 <a class="header-anchor" href="#轮换-tang-服务器密钥" aria-label="Permalink to “轮换 Tang 服务器密钥”">​</a></h3><p>最好定期轮换 Tang 服务器密钥，并更新 Stratis 客户服务器以使用新的 Tang 密钥。</p><p>要生成新的 Tang 密钥，首先登录到 Tang 服务器，查看 <code>/var/db/tang</code> 目录的当前状态。然后，运行 <code>tang-show-keys</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -al /var/db/tang</span></span>
<span class="line"><span>total 8</span></span>
<span class="line"><span>drwx------. 1 tang tang 124 Mar 15 15:51 .</span></span>
<span class="line"><span>drwxr-xr-x. 1 root root 16 Mar 15 15:48 ..</span></span>
<span class="line"><span>-rw-r--r--. 1 tang tang 361 Mar 15 15:51 hbjJEDXy8G8wynMPqiq8F47nJwo.jwk</span></span>
<span class="line"><span>-rw-r--r--. 1 tang tang 367 Mar 15 15:51 l3fZGUCmnvKQF_OA6VZF9jf8z2s.jwk</span></span>
<span class="line"><span># tang-show-keys</span></span>
<span class="line"><span>l3fZGUCmnvKQF_OA6VZF9jf8z2s</span></span></code></pre></div><p>要生成新的密钥，运行 <code>tangd-keygen</code> 并将其指向 <code>/var/db/tang</code> 目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /usr/libexec/tangd-keygen /var/db/tang</span></span></code></pre></div><p>如果你再看看 <code>/var/db/tang</code> 目录，你会看到两个新文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -al /var/db/tang</span></span>
<span class="line"><span>total 16</span></span>
<span class="line"><span>drwx------. 1 tang tang 248 Mar 22 10:41 .</span></span>
<span class="line"><span>drwxr-xr-x. 1 root root 16 Mar 15 15:48 ..</span></span>
<span class="line"><span>-rw-r--r--. 1 tang tang 361 Mar 15 15:51 hbjJEDXy8G8wynMPqiq8F47nJwo.jwk</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 354 Mar 22 10:41 iyG5HcF01zaPjaGY6L_3WaslJ_E.jwk</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 349 Mar 22 10:41 jHxerkqARY1Ww_H_8YjQVZ5OHao.jwk</span></span>
<span class="line"><span>-rw-r--r--. 1 tang tang 367 Mar 15 15:51 l3fZGUCmnvKQF_OA6VZF9jf8z2s.jwk</span></span></code></pre></div><p>如果你运行 <code>tang-show-keys</code>，就会显示出 Tang 所公布的密钥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tang-show-keys</span></span>
<span class="line"><span>l3fZGUCmnvKQF_OA6VZF9jf8z2s</span></span>
<span class="line"><span>iyG5HcF01zaPjaGY6L_3WaslJ_E</span></span></code></pre></div><p>你可以通过将两个原始文件改名为以句号开头的隐藏文件，来防止旧的密钥（以 <code>l3fZ</code> 开头）被公布。通过这种方法，旧的密钥将不再被公布，但是它仍然可以被任何没有更新为使用新密钥的现有客户端使用。一旦所有的客户端都更新使用了新密钥，这些旧密钥文件就可以删除了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cd /var/db/tang</span></span>
<span class="line"><span># mv hbjJEDXy8G8wynMPqiq8F47nJwo.jwk   .hbjJEDXy8G8wynMPqiq8F47nJwo.jwk</span></span>
<span class="line"><span># mv l3fZGUCmnvKQF_OA6VZF9jf8z2s.jwk   .l3fZGUCmnvKQF_OA6VZF9jf8z2s.jwk</span></span></code></pre></div><p>此时，如果再运行 <code>tang-show-keys</code>，Tang 只公布新钥匙：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tang-show-keys</span></span>
<span class="line"><span>iyG5HcF01zaPjaGY6L_3WaslJ_E</span></span></code></pre></div><p>下一步，切换到你的 Stratis 系统并更新它以使用新的 Tang 密钥。当文件系统在线时， Stratis 支持这样做。</p><p>首先，解除对池的绑定：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool unbind pool1</span></span></code></pre></div><p>接下来，用创建加密池时使用的原始口令设置密钥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis key set --capture-key pool1key</span></span>
<span class="line"><span>Enter key data followed by the return key:</span></span></code></pre></div><p>最后，用更新后的密钥指纹将 Stratis 池绑定到 Tang 服务器上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool bind nbde pool1 pool1key http://tang-server --thumbprint iyG5HcF01zaPjaGY6L_3WaslJ_E</span></span></code></pre></div><p>Stratis 系统现在配置为使用更新的 Tang 密钥。一旦使用旧的 Tang 密钥的任何其他客户系统被更新，在 Tang 服务器上的 <code>/var/db/tang</code> 目录中被重命名为隐藏文件的两个原始密钥文件就可以被备份和删除了。</p><h3 id="如果-tang-服务器不可用怎么办" tabindex="-1">如果 Tang 服务器不可用怎么办？ <a class="header-anchor" href="#如果-tang-服务器不可用怎么办" aria-label="Permalink to “如果 Tang 服务器不可用怎么办？”">​</a></h3><p>接下来，关闭 Tang 服务器，模拟它不可用，然后重启 Stratis 系统。</p><p>重启后，Stratis 池又不可用了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool list</span></span>
<span class="line"><span>Name Total Physical Properties</span></span></code></pre></div><p>如果你试图用 NBDE 解锁，会因为 Tang 服务器不可用而失败：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool unlock clevis</span></span>
<span class="line"><span>Execution failed:</span></span>
<span class="line"><span>An iterative command generated one or more errors: The operation &#39;unlock&#39; on a resource of type pool failed. The following errors occurred:</span></span>
<span class="line"><span>Partial action &quot;unlock&quot; failed for pool with UUID 4d62f840f2bb4ec9ab53a44b49da3f48: Cryptsetup error: Failed with error: Error: Command failed: cmd: &quot;clevis&quot; &quot;luks&quot; &quot;unlock&quot; &quot;-d&quot; &quot;/dev/vdb&quot; &quot;-n&quot; &quot;stratis-1-private-42142fedcb4c47cea2e2b873c08fcf63-crypt&quot;, exit reason: 1 stdout: stderr: /dev/vdb could not be opened.</span></span></code></pre></div><p>此时，在 Tang 服务器无法到达的情况下，解锁池的唯一选择就是使用原密钥口令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis key set --capture-key pool1key</span></span>
<span class="line"><span>Enter key data followed by the return key:</span></span></code></pre></div><p>然后你可以使用钥匙解锁池：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool unlock keyring</span></span></code></pre></div><p>接下来，验证池是否成功解锁：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool list</span></span>
<span class="line"><span>Name Total Physical Properties</span></span>
<span class="line"><span>pool1 4.98 GiB / 583.65 MiB / 4.41 GiB ~Ca, Cr</span></span></code></pre></div><hr>`,69)),i("p",null,[s[26]||(s[26]=a("via: ",-1)),n(t,{href:"https://fedoramagazine.org/network-bound-disk-encryption-with-stratis/"},{default:e(()=>[...s[25]||(s[25]=[a("https://fedoramagazine.org/network-bound-disk-encryption-with-stratis/",-1)])]),_:1})]),i("p",null,[s[31]||(s[31]=a("作者：",-1)),n(t,{href:"https://fedoramagazine.org/author/briansmith/"},{default:e(()=>[...s[27]||(s[27]=[a("briansmith",-1)])]),_:1}),s[32]||(s[32]=a(" 选题：",-1)),n(t,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[28]||(s[28]=[a("lujun9972",-1)])]),_:1}),s[33]||(s[33]=a(" 译者：",-1)),n(t,{href:"https://github.com/wxy"},{default:e(()=>[...s[29]||(s[29]=[a("wxy",-1)])]),_:1}),s[34]||(s[34]=a(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:e(()=>[...s[30]||(s[30]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[37]||(s[37]=a("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[35]||(s[35]=[a("LCTT",-1)])]),_:1}),s[38]||(s[38]=a(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:e(()=>[...s[36]||(s[36]=[a("Linux中国",-1)])]),_:1}),s[39]||(s[39]=a(" 荣誉推出",-1))])])}const C=l(g,[["render",h]]);export{v as __pageData,C as default};
